def render_dataset_cards(preloaded_datasets):
    """
    Render dataset info as visually appealing cards with colors and icons.
    """
    html_cards = ""
    for name, meta in preloaded_datasets.items():
        df = meta["df"]
        rows = df.shape[0]
        cols = df.shape[1]
        ts_len = meta["meta"].get("T", "N/A")
        classes = df['label'].nunique() if 'label' in df.columns else "N/A"
        path = meta.get("path", "N/A")

        # Color based on dataset size
        if rows > 5000:
            color = "#FF6B6B"  # large dataset - redish
        elif rows > 2000:
            color = "#FFA94D"  # medium - orange
        else:
            color = "#4DABF7"  # small - blue

        html_cards += f"""
        <div class='dataset-card' style='background-color:{color};'>
            <h3>{name}</h3>
            <p>🗂 Rows: <b>{rows}</b></p>
            <p>📊 Columns: <b>{cols}</b></p>
            <p>⏱ TS Length: <b>{ts_len}</b></p>
            <p>🎯 Classes: <b>{classes}</b></p>
            <p style='font-size:12px;'>ℹ️ Path: {path}</p>
        </div>
        """

    # Wrap all cards in a flex container
    html = f"""
    <style>
    .dataset-container {{
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        justify-content: flex-start;
    }}
    .dataset-card {{
        flex: 0 1 200px;
        border-radius: 12px;
        padding: 12px;
        color: white;
        font-family: Arial, sans-serif;
        box-shadow: 0px 2px 8px rgba(0,0,0,0.2);
        transition: transform 0.2s;
    }}
    .dataset-card:hover {{
        transform: scale(1.05);
        box-shadow: 0px 4px 12px rgba(0,0,0,0.3);
    }}
    .dataset-card h3 {{
        margin: 0 0 8px 0;
        font-size: 16px;
        text-align: center;
    }}
    .dataset-card p {{
        margin: 4px 0;
        font-size: 13px;
        text-align: center;
    }}
    </style>
    <div class="dataset-container">
        {html_cards}
    </div>
    """
    return html


